const QUESTION_SET_VERSION="2026-11-v2",QUESTIONS=[{id:1,chapter:"daily",dimension:"IM",text:"看到动漫或剧里的「可爱日常」桥段时，你会？",textEn:"When you see a 'cute everyday life' scene in an anime or show, what do you do?",options:[{label:"A",text:"会代入，还会研究她们房间的布置和配色，想把那种氛围搬进自己的生活。",textEn:"I imagine myself in it, study the room setup and colors, and want to bring that atmosphere into my own life.",score:{IM:2,AE:1}},{label:"B",text:"画面好看就多看两眼，剧情合理才继续追。",textEn:"I enjoy the visuals for a moment, and keep watching only if the story holds up.",score:{IM:0}},{label:"C",text:"先吐槽设定不合理，好看不能当饭吃。",textEn:"I poke at the unrealistic setup first—pretty visuals alone don't carry a story.",score:{IM:-2,AN:1,HU:1}}]},{id:2,chapter:"daily",dimension:"SO",text:"朋友临时组局，说就差你了，你？",textEn:"Friends throw together a last-minute meetup and say they're just missing you. What do you do?",options:[{label:"A",text:"已经在换衣服了，人多才热闹。",textEn:"I'm already changing—the more people, the better.",score:{SO:2,EX:1}},{label:"B",text:"看是谁组织的、都有谁，再决定。",textEn:"Depends on who organized it and who's going.",score:{SO:0}},{label:"C",text:"更想按原计划待着，下次一定。",textEn:"I'd rather stick with my original plan. Next time for sure.",score:{SO:-2,PL:1}}]},{id:3,chapter:"daily",dimension:"PL",text:"你有护肤、整理或健康管理的固定流程吗？",textEn:"Do you have a fixed routine for skincare, tidying up, or health?",options:[{label:"A",text:"有一套固定顺序，打乱了会重新来。",textEn:"Yes—a fixed order. If it gets disrupted, I start over.",score:{PL:2,AE:1,RT:1}},{label:"B",text:"大概有，但看当天心情。",textEn:"Sort of, but it depends on my mood that day.",score:{PL:0}},{label:"C",text:"能省就省，舒服最重要。",textEn:"I keep it minimal—comfort matters most.",score:{PL:-2,AE:-1}}]},{id:4,chapter:"daily",dimension:"EX",text:"发一条生活动态时，你通常会？",textEn:"When you post something about your life, what do you usually do?",options:[{label:"A",text:"认真排版、配文、挑封面，发出去要像个作品。",textEn:"Lay it out carefully, write a caption, pick a cover—it should look like a piece of work.",score:{EX:2,IM:1,AE:1}},{label:"B",text:"偶尔发，随手记录，不折腾。",textEn:"I post occasionally, just a casual record—no fuss.",score:{EX:0}},{label:"C",text:"更爱看别人发，自己几乎不发。",textEn:"I'd rather watch what others post; I rarely post myself.",score:{EX:-2,CU:1}}]},{id:5,chapter:"daily",dimension:"SO",text:"哪种场合最让你觉得「充电」？",textEn:"Which setting recharges you most?",options:[{label:"A",text:"一大群人热热闹闹，回家还在回味。",textEn:"A big, lively group—I'm still replaying it on the way home.",score:{SO:2,EX:1}},{label:"B",text:"三五个熟人刚好，太多会累。",textEn:"Three or four familiar faces is just right; too many gets tiring.",score:{SO:0}},{label:"C",text:"一个人待着最充电，社交是耗电项。",textEn:"Time alone recharges me—socializing drains the battery.",score:{SO:-2}}]},{id:6,chapter:"daily",dimension:"AE",text:"看到照片里的自己，你的第一反应通常是？",textEn:"When you see a photo of yourself, what's your first reaction?",options:[{label:"A",text:"会研究角度、光线、构图，想着下次怎么拍得更好。",textEn:"I study the angle, lighting, and framing, and think about how to shoot it better next time.",score:{AE:2,AN:1}},{label:"B",text:"还行就看，不好看就划走。",textEn:"If it's okay I'll look; if not, I scroll past.",score:{AE:0}},{label:"C",text:"不太在意，照片能看清人就行。",textEn:"I don't care much—as long as you can tell it's me.",score:{AE:-2}}]},{id:7,chapter:"daily",dimension:"AE",text:"你的衣橱或收藏是怎么组织的？",textEn:"How do you organize your closet or collection?",options:[{label:"A",text:"按风格和场合分好区，还会定期整理搭配。",textEn:"Sorted by style and occasion, and I regularly rework outfits.",score:{AE:2,IM:1,PL:1}},{label:"B",text:"有几件特别喜欢的，其他够穿就行。",textEn:"A few favorites, and the rest just needs to be wearable.",score:{AE:0}},{label:"C",text:"实用为主，能穿就行。",textEn:"Practical first—if it works, it works.",score:{AE:-2}}]},{id:8,chapter:"daily",dimension:"PL",text:"周末突然空出一整天，你会？",textEn:"A whole weekend day suddenly opens up. What do you do?",options:[{label:"A",text:"立刻列一个想做的事清单，按顺序打卡。",textEn:"Immediately make a list of things I want to do and work through it.",score:{PL:2,RT:1}},{label:"B",text:"先睡到自然醒，再决定干嘛。",textEn:"Sleep in first, then decide.",score:{PL:0}},{label:"C",text:"什么都不安排，走到哪算哪。",textEn:"Plan nothing—see where the day takes me.",score:{PL:-2,CU:1}}]},{id:9,chapter:"daily",dimension:"AN",text:"有人评价你的外表或穿搭，你会？",textEn:"Someone comments on your looks or outfit. What do you do?",options:[{label:"A",text:"会琢磨对方为什么这么说，甚至复盘一下。",textEn:"I wonder why they said it and even replay it in my head.",score:{AN:2,MO:1}},{label:"B",text:"听过就算，合不合理自己判断。",textEn:"I hear it and move on—I judge for myself whether it's fair.",score:{AN:0}},{label:"C",text:"觉得这种评价挺没意思，换个话题。",textEn:"I find that kind of comment pointless and change the subject.",score:{AN:-1,MO:-1,HU:1}}]},{id:10,chapter:"taste",dimension:"IM",text:"对「梦幻感」这个词，你的第一反应是？",textEn:"What's your first reaction to the word 'whimsical'?",options:[{label:"A",text:"很吃这一套，会主动把这种感觉放进生活里。",textEn:"I'm into it and actively bring that feeling into my life.",score:{IM:2,AE:1}},{label:"B",text:"看作品和场合，好看就欣赏，不代入。",textEn:"It depends on the work and the setting—I can appreciate it without stepping into it.",score:{IM:0}},{label:"C",text:"不是我的审美，我更偏爱别的风格。",textEn:"It's not my taste—I prefer other styles.",score:{IM:-2,CU:1}}]},{id:11,chapter:"taste",dimension:"AN",text:"当你需要确认一个想法时，你更倾向？",textEn:"When you need to be sure about an idea, what do you lean on?",options:[{label:"A",text:"先收集信息、列利弊，再下结论。",textEn:"Gather information, list pros and cons, then decide.",score:{AN:2,PL:1}},{label:"B",text:"感觉和信息各占一半。",textEn:"Half feeling, half information.",score:{AN:0}},{label:"C",text:"先凭直觉走，走不通再调整。",textEn:"Follow my gut first, adjust if it doesn't work.",score:{AN:-2,PL:-1}}]},{id:12,chapter:"taste",dimension:"AE",text:"你的手机相册更接近哪种状态？",textEn:"Which describes your phone gallery better?",options:[{label:"A",text:"有专门分类的相册，会挑出满意的照片。",textEn:"I have categorized albums and pick out the shots I'm happy with.",score:{AE:2,EX:1}},{label:"B",text:"随手拍，几乎不整理。",textEn:"I snap things casually and almost never organize.",score:{AE:0}},{label:"C",text:"很少拍自己，更爱拍风景和东西。",textEn:"I rarely photograph myself—I prefer landscapes and objects.",score:{AE:-2,CU:1}}]},{id:13,chapter:"taste",dimension:"SO",text:"一个人在家待了一周，你感觉？",textEn:"After a week alone at home, how do you feel?",options:[{label:"A",text:"第三天就开始找人说话。",textEn:"By day three I'm already looking for someone to talk to.",score:{SO:2,EX:1}},{label:"B",text:"一半独处一半社交，刚好。",textEn:"Half alone, half social—that's about right.",score:{SO:0}},{label:"C",text:"非常享受，最好别有人打扰。",textEn:"I love it—ideally nobody interrupts.",score:{SO:-2}}]},{id:14,chapter:"taste",dimension:"EX",text:"有人夸你「很有品味」，你会？",textEn:"Someone says you have great taste. What do you do?",options:[{label:"A",text:"很开心，顺势聊起自己喜欢的风格。",textEn:"I'm happy and happily start talking about the styles I like.",score:{EX:2,SO:1}},{label:"B",text:"说声谢谢，心里暗爽一下。",textEn:"Say thanks and quietly enjoy it.",score:{EX:0}},{label:"C",text:"有点不知道怎么接，转移话题。",textEn:"I'm not sure how to respond and change the subject.",score:{EX:-2}}]},{id:15,chapter:"taste",dimension:"PL",text:"给自己定一个目标时，你通常会？",textEn:"When you set a goal for yourself, what do you usually do?",options:[{label:"A",text:"写下来，拆成阶段，定期回看。",textEn:"Write it down, break it into stages, and review regularly.",score:{PL:2,AN:1}},{label:"B",text:"有方向，但保留调整空间。",textEn:"I have a direction but leave room to adjust.",score:{PL:0}},{label:"C",text:"不喜欢框架，走一步看一步。",textEn:"I don't like frameworks—one step at a time.",score:{PL:-2,CU:1}}]},{id:16,chapter:"taste",dimension:"AN",text:"有人说「你看起来不像会喜欢这种东西的人」，你会？",textEn:"Someone says, 'You don't look like the type who'd like this.' What do you do?",options:[{label:"A",text:"会认真讨论这句话背后的刻板印象。",textEn:"I'll seriously discuss the stereotype behind that comment.",score:{AN:2,EX:1}},{label:"B",text:"笑一笑，看对方是不是在开玩笑。",textEn:"Smile and see whether they're joking.",score:{AN:0}},{label:"C",text:"懒得接，直接换话题。",textEn:"Not worth engaging—I change the subject.",score:{AN:-2,EX:-1}}]},{id:17,chapter:"taste",dimension:"SO",text:"一个人去一家从没去过的咖啡店，你会？",textEn:"Going alone to a coffee shop you've never tried—what do you do?",options:[{label:"A",text:"坐吧台，和店员聊两句，顺便探探店。",textEn:"Sit at the bar, chat with the staff, and explore the place.",score:{SO:2,CU:1}},{label:"B",text:"找个角落，戴上耳机，各干各的。",textEn:"Find a corner, put on headphones, and do my own thing.",score:{SO:0}},{label:"C",text:"不太想一个人去，宁愿换个熟悉的地方。",textEn:"I'd rather not go alone—I'd pick somewhere familiar.",score:{SO:-2,CU:-1}}]},{id:18,chapter:"taste",dimension:"AN",text:"别人说「别想太多，跟着感觉走就好」，你觉得？",textEn:"Someone says, 'Don't overthink it, just go with your feelings.' What do you think?",options:[{label:"A",text:"认同，感觉往往比分析更准。",textEn:"I agree—feelings are often more accurate than analysis.",score:{AN:-2}},{label:"B",text:"两者都需要，看事情大小。",textEn:"Both matter, depending on how big the decision is.",score:{AN:0}},{label:"C",text:"感觉是线索，但还是想验证一下。",textEn:"Feelings are clues, but I still want to verify them.",score:{AN:2,PL:1}}]},{id:19,chapter:"taste",dimension:"AE",text:"布置自己的房间或工位时，你会？",textEn:"When setting up your room or desk, what do you do?",options:[{label:"A",text:"认真搭配颜色和摆件，弄成自己喜欢的样子。",textEn:"Carefully match colors and objects until it feels like mine.",score:{AE:2,RT:2,IM:1}},{label:"B",text:"舒服整洁就行，不太讲究风格。",textEn:"Comfortable and tidy is enough—style isn't a priority.",score:{AE:0}},{label:"C",text:"能住就行，装饰是额外负担。",textEn:"As long as it's livable—decorating is extra work.",score:{AE:-2,RT:-2}}]},{id:20,chapter:"social",dimension:"SO",text:"遇到和你兴趣相同的人，你会？",textEn:"When you meet someone with the same interests, what do you do?",options:[{label:"A",text:"很需要，和同好聊天能回血。",textEn:"I need that—talking with fellow fans recharges me.",score:{SO:2,EX:1}},{label:"B",text:"有更好，没有也能自己玩。",textEn:"Nice to have; I can also enjoy it on my own.",score:{SO:0}},{label:"C",text:"自己玩更自在，不太主动找组织。",textEn:"I'm more comfortable on my own and don't seek out groups.",score:{SO:-2}}]},{id:21,chapter:"social",dimension:"AE",text:"为喜欢的事情分配预算时，你通常？",textEn:"When budgeting for something you love, what do you usually do?",options:[{label:"A",text:"会专门留一笔预算，提前想好买什么。",textEn:"I set aside a budget and plan what to get.",score:{AE:2,PL:1}},{label:"B",text:"看情况，遇到特别喜欢的才下手。",textEn:"Depends—I buy when something really catches me.",score:{AE:0}},{label:"C",text:"更愿意把钱花在别的地方。",textEn:"I'd rather spend the money elsewhere.",score:{AE:-2}}]},{id:22,chapter:"social",dimension:"EX",text:"在工作或学校里，你会怎么处理自己的兴趣？",textEn:"At work or school, how do you handle your personal interests?",options:[{label:"A",text:"大方分享，别人问就聊。",textEn:"Share openly—if someone asks, I'll talk about it.",score:{EX:2,SO:1}},{label:"B",text:"分场合，熟人面前会说。",textEn:"Depends on the setting; I'll mention it around people I know.",score:{EX:0}},{label:"C",text:"工作和兴趣分开，保持低调。",textEn:"Keep work and interests separate—stay low-key.",score:{EX:-2,PL:1}}]},{id:23,chapter:"social",dimension:"AN",text:"群聊里有人说了和你不同的观点，你会？",textEn:"Someone in a group chat shares a view different from yours. What do you do?",options:[{label:"A",text:"加入讨论，把自己的理由讲清楚。",textEn:"Join in and explain my reasoning.",score:{AN:2,EX:1}},{label:"B",text:"看看就好，不急着站队。",textEn:"Just read—no rush to pick a side.",score:{AN:0}},{label:"C",text:"直接划走，不想把时间花在这。",textEn:"Scroll past—not worth my time.",score:{AN:-2,EX:-1}}]},{id:24,chapter:"social",dimension:"AN",text:"有人问了一个你不想回答的私人问题，你会？",textEn:"Someone asks a personal question you'd rather not answer. What do you do?",options:[{label:"A",text:"直接说这个不想聊，换个话题。",textEn:"Say directly that I'd rather not discuss it and change the subject.",score:{AN:1,EX:1}},{label:"B",text:"含糊带过，看对方反应。",textEn:"Give a vague answer and see how they react.",score:{AN:0}},{label:"C",text:"顺着聊两句，再自然转开。",textEn:"Chat briefly, then steer away naturally.",score:{AN:0,EX:1}}]},{id:25,chapter:"social",dimension:"EX",text:"你的社交媒体使用方式更接近？",textEn:"Which best describes how you use social media?",options:[{label:"A",text:"主号什么都发，生活就是公开的。",textEn:"One main account—I post whatever, my life is public.",score:{EX:2,SO:1}},{label:"B",text:"分账号，不同圈子看不同内容。",textEn:"Separate accounts—different circles see different things.",score:{EX:0}},{label:"C",text:"基本只看不发，当观众挺舒服。",textEn:"Mostly watch, rarely post—being an audience is comfortable.",score:{EX:-2}}]},{id:26,chapter:"social",dimension:"EX",text:"新认识的朋友问你平时喜欢什么，你会？",textEn:"A new friend asks what you're into. What do you do?",options:[{label:"A",text:"热情安利，能聊半小时。",textEn:"Enthusiastically recommend things—I could talk for half an hour.",score:{EX:2,SO:1}},{label:"B",text:"简单说两句，看对方感不感兴趣。",textEn:"Mention a couple of things and see if they're interested.",score:{EX:0}},{label:"C",text:"先反问对方，听听再说。",textEn:"Ask them first and listen before sharing.",score:{EX:-1,AN:1}}]},{id:27,chapter:"social",dimension:"AN",text:"遇到一个棘手的难题，你第一步是？",textEn:"When you hit a tricky problem, what's your first step?",options:[{label:"A",text:"先自己查资料、做功课。",textEn:"Research it and do my homework first.",score:{AN:2,PL:1}},{label:"B",text:"先问朋友，边聊边想。",textEn:"Ask a friend and think it through while talking.",score:{AN:0}},{label:"C",text:"找人一起想办法，人多思路多。",textEn:"Get people together—more heads, more ideas.",score:{AN:-1,SO:2}}]},{id:28,chapter:"social",dimension:"CU",text:"刷到一个完全陌生领域的资料，你会？",textEn:"You come across material from a completely unfamiliar field. What do you do?",options:[{label:"A",text:"立刻点进去，顺着链接越看越远。",textEn:"Click in immediately and follow the links down a rabbit hole.",score:{CU:2,AN:1}},{label:"B",text:"先收藏，有空再看。",textEn:"Save it for later.",score:{CU:0}},{label:"C",text:"不太感兴趣，除非跟当前的事有关。",textEn:"Not very interested unless it's relevant to what I'm doing.",score:{CU:-2}}]},{id:29,chapter:"social",dimension:"RT",text:"出门前，你有固定的「小仪式」吗？",textEn:"Do you have a fixed little ritual before going out?",options:[{label:"A",text:"有，不做完这套流程就出不了门。",textEn:"Yes—I can't leave until I've finished the routine.",score:{RT:2,AE:1,PL:1}},{label:"B",text:"看时间，充裕就慢慢来。",textEn:"Depends on time—if I have it, I take it slow.",score:{RT:0}},{label:"C",text:"没什么仪式，拿上东西就走。",textEn:"No ritual—grab my things and go.",score:{RT:-2,PL:-1}}]},{id:30,chapter:"future",dimension:"AE",text:"日常出门时，你会花多少心思在搭配上？",textEn:"On a normal day out, how much thought do you put into your outfit?",options:[{label:"A",text:"每天都会认真想穿什么、怎么搭。",textEn:"Every day I think carefully about what to wear and how to combine it.",score:{AE:2,RT:1,IM:1}},{label:"B",text:"看场合，重要日子会认真。",textEn:"Depends on the occasion—I make an effort for important days.",score:{AE:0}},{label:"C",text:"舒服优先，搭配不是重点。",textEn:"Comfort first—matching isn't the priority.",score:{AE:-2}}]},{id:31,chapter:"future",dimension:"PL",text:"对待一个长期爱好，你通常？",textEn:"How do you usually handle a long-term hobby?",options:[{label:"A",text:"有固定的投入节奏，会记录进展。",textEn:"I keep a steady rhythm and track my progress.",score:{PL:2,CU:1,RT:1}},{label:"B",text:"想起来就做，忙了就停。",textEn:"I do it when I remember and pause when busy.",score:{PL:0}},{label:"C",text:"兴趣换得快，很少长期投入一项。",textEn:"My interests rotate quickly—I rarely stick with one for long.",score:{PL:-2,CU:1}}]},{id:32,chapter:"future",dimension:"MO",text:"整整一个月没时间做自己喜欢的事，你会？",textEn:"If you had no time for what you love for a whole month, how would you feel?",options:[{label:"A",text:"会明显低落，感觉生活少了点什么。",textEn:"Noticeably down—something would feel missing.",score:{MO:2,IM:1}},{label:"B",text:"有点想念，但能等。",textEn:"I'd miss it a bit, but I can wait.",score:{MO:0}},{label:"C",text:"还好，忙别的也能过得不错。",textEn:"Fine—I can enjoy other things too.",score:{MO:-2,AN:1}}]},{id:33,chapter:"future",dimension:"EX",text:"如果外界的评价突然都消失了，你会？",textEn:"If outside opinions suddenly disappeared, what would you do?",options:[{label:"A",text:"会更敢表达，想尝试一直没试的风格。",textEn:"I'd express myself more freely and try styles I've held back on.",score:{EX:2,IM:1}},{label:"B",text:"生活大概照旧，只是心里轻松点。",textEn:"Life would mostly stay the same—just lighter inside.",score:{EX:0}},{label:"C",text:"本来就不太看外界，影响不大。",textEn:"I don't pay much attention to outside opinions anyway.",score:{EX:-1,AN:1}}]},{id:34,chapter:"future",dimension:"IM",text:"对你来说，「做自己」最重要的是？",textEn:"For you, what matters most about 'being yourself'?",options:[{label:"A",text:"跟着内心审美走，喜欢什么就靠近什么。",textEn:"Follow my inner sense of beauty—move toward what I love.",score:{IM:2,AE:1}},{label:"B",text:"在现实和内心之间找平衡。",textEn:"Find a balance between reality and inner self.",score:{IM:0}},{label:"C",text:"先看清现实条件，再做选择。",textEn:"Understand the real constraints first, then choose.",score:{IM:-2,AN:1}}]},{id:35,chapter:"future",dimension:"PL",text:"你有没有认真想过五年后的自己？",textEn:"Have you seriously thought about who you'll be in five years?",options:[{label:"A",text:"有清晰目标，也知道大概怎么走。",textEn:"Yes—clear goals and a rough sense of the path.",score:{PL:2,AN:1}},{label:"B",text:"大概想过，但不写死。",textEn:"Roughly, but I don't lock it in.",score:{PL:0}},{label:"C",text:"不爱做长期计划，留点未知才有意思。",textEn:"I don't like long-term plans—a little uncertainty is fun.",score:{PL:-2,CU:1}}]},{id:36,chapter:"future",dimension:"AE",text:"遇到真正喜欢的东西，你通常会？",textEn:"When you find something you truly love, what do you usually do?",options:[{label:"A",text:"会为它单独留预算，觉得值。",textEn:"Set aside a budget for it—it's worth it.",score:{AE:2,PL:1}},{label:"B",text:"量力而行，偶尔奖励自己。",textEn:"Spend within my means and reward myself occasionally.",score:{AE:0}},{label:"C",text:"更愿意把钱花在体验或别的地方。",textEn:"I'd rather spend on experiences or other things.",score:{AE:-2,CU:1}}]},{id:37,chapter:"future",dimension:"PL",text:"想长期改变一种生活方式（比如作息、运动、兴趣），你会？",textEn:"If you wanted to change a long-term habit (sleep, exercise, a hobby), what would you do?",options:[{label:"A",text:"查资料、定计划，按阶段执行。",textEn:"Research it, make a plan, and follow it in stages.",score:{PL:2,AN:1}},{label:"B",text:"边做边调整，不追求完美方案。",textEn:"Start and adjust as I go—no perfect plan needed.",score:{PL:0}},{label:"C",text:"顺其自然，不太想给自己上强度。",textEn:"Let it happen naturally—I don't want to push myself too hard.",score:{PL:-2}}]},{id:38,chapter:"future",dimension:"MO",text:"你对「现在的自己」的整体态度是？",textEn:"What's your overall attitude toward your current self?",options:[{label:"A",text:"挺满意，能看到自己一步步的变化。",textEn:"Pretty satisfied—I can see how I've changed step by step.",score:{MO:1,PL:1}},{label:"B",text:"有满意也有想改的，慢慢来。",textEn:"Some things I like, some I want to change—taking it slow.",score:{MO:0}},{label:"C",text:"不太想现在评价，先过着再说。",textEn:"I'd rather not evaluate it right now—just live for a while.",score:{MO:0,AN:-1}}]},{id:39,chapter:"future",dimension:"HU",nonScoring:!0,text:"最后一题：你为什么点进这个测试？",textEn:"Last question: why did you click into this quiz?",options:[{label:"A",text:"想看看自己像哪种角色，图一乐。",textEn:"I wanted to see which character I resemble—just for fun.",score:{}},{label:"B",text:"朋友发来的，随便做做。",textEn:"A friend sent it—I'm doing it casually.",score:{}},{label:"C",text:"好奇点进来，看看这玩意到底准不准。",textEn:"Curiosity brought me here—let's see how accurate it is.",score:{}}]}];"undefined"!=typeof module&&(module.exports={QUESTIONS:QUESTIONS,QUESTION_SET_VERSION:"2026-11-v2"});